from __future__ import annotations

import json
from pathlib import Path


ASSETS = Path(r"D:\OIiglot_Bulgary\app\src\main\assets")


def load_lesson(lesson_id: int) -> dict:
    path = ASSETS / f"textbook_exercises_lesson{lesson_id}.json"
    return json.loads(path.read_text(encoding="utf-8"))


def save_lesson(lesson_id: int, payload: dict) -> None:
    path = ASSETS / f"textbook_exercises_lesson{lesson_id}.json"
    path.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def item(lesson: int, num: int, theme: str, grammar: list[str], bg: str, ru: str, uk: str, words: list[str], distractors: list[str], hint_ru: str, hint_uk: str, difficulty: str = "easy") -> dict:
    return {
        "id": f"l{lesson}_t_{num:03d}",
        "theme": theme,
        "grammarFocus": grammar,
        "difficulty": difficulty,
        "bg": bg,
        "ru": ru,
        "uk": uk,
        "correctWords": words,
        "distractors": distractors,
        "hintRu": hint_ru,
        "hintUk": hint_uk,
    }


def ensure_count(lesson_id: int, extra_items: list[dict]) -> None:
    payload = load_lesson(lesson_id)
    payload["items"] = payload["items"][:20] + extra_items
    if len(payload["items"]) != 50:
        raise ValueError(f"Lesson {lesson_id} expected 50 items, got {len(payload['items'])}")
    save_lesson(lesson_id, payload)


